import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { toast } from "react-toastify";
import API from "../services/api";
import Loader from "../components/Loader";

function Dashboard() {
  const [blogs, setBlogs] = useState([]);
  const [loading, setLoading] = useState(true);

  const user = JSON.parse(localStorage.getItem("user"));

  useEffect(() => {
    getBlogs();
  }, []);

  const getBlogs = async () => {
    try {
      const response = await API.get("/blogs");

      const myBlogs = response.data.filter(
        (blog) => blog.author === user?.name,
      );

      setBlogs(myBlogs);
    } catch (error) {
      toast.error("Unable to load blogs");
    } finally {
      setLoading(false);
    }
  };

  const deleteBlog = async (id) => {
    const confirmDelete = window.confirm(
      "Are you sure you want to delete this blog?",
    );

    if (!confirmDelete) return;

    try {
      await API.delete(`/blogs/${id}`);

      setBlogs(blogs.filter((blog) => blog.id !== id));

      toast.success("Blog deleted successfully", {
        autoClose: 1500,
      });
    } catch (error) {
      toast.error("Failed to delete blog", {
        autoClose: 1500,
      });
    }
  };

  return (
    <div className="dashboard">
      <div className="dashboard-header">
        <div>
          <span className="small-title">👋 Welcome back</span>

          <h1>{user?.name || "User"}</h1>

          <p>Manage your published stories.</p>
        </div>

        <Link to="/create-blog" className="create-btn">
          + Create Blog
        </Link>
      </div>

      <div className="dashboard-stats">
        <div className="stat-card">
          <span>📝</span>
          <div>
            <h3>{blogs.length}</h3>
            <p>Total Blogs</p>
          </div>
        </div>

        <div className="stat-card">
          <span>👤</span>
          <div>
            <h3>{user?.name}</h3>
            <p>Author</p>
          </div>
        </div>
      </div>

      <div className="dashboard-content">
        <h2>My Blogs</h2>

        {loading ? (
          <Loader />
        ) : blogs.length === 0 ? (
          <div className="empty-box">
            <h3>No blogs yet ✍️</h3>
            <p>Create your first blog post.</p>

            <Link to="/create-blog" className="hero-btn">
              Create Blog
            </Link>
          </div>
        ) : (
          <div className="dashboard-blog-grid">
            {blogs.map((blog) => (
              <div className="dashboard-blog-card" key={blog.id}>
                <h3>{blog.title}</h3>

                <p>{blog.content.substring(0, 120)}...</p>

                <div className="dashboard-actions">
                  <Link to={`/blog/${blog.id}`} className="view-btn">
                    View
                  </Link>

                  <Link to={`/edit-blog/${blog.id}`} className="edit-btn">
                    Edit
                  </Link>

                  <button
                    onClick={() => deleteBlog(blog.id)}
                    className="delete-btn"
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default Dashboard;
